START TRANSACTION;

INSERT INTO convocatoria_content (torneoid, section_id, section_type, content, enabled) VALUES (365, 'reglas_intro_cards', 'cards', '[{"icon": "BookOpen", "title": "Reglas USGA", "body": "Se jugará bajo las Reglas de Golf de la USGA 2026, así mismo se aplicarán las reglas locales, con sus condiciones y definiciones. Dejan sin efecto otras utilizadas en otros torneos, incluyendo las propias del score card del Club o cualquier otro documento."}, {"icon": "Gavel", "title": "Árbitro del Torneo", "body": "Sr. Alfonso Navarro — Asistencia de Reglas: Tel. 662 104 7508. La penalidad por infringir alguna de las presentes será de dos golpes."}, {"icon": "Clock", "title": "Ritmo de juego", "body": "Debe jugarse a un ritmo rápido. Procurar no separarse del grupo que va al frente. Grupo fuera de posición recibirá una llamada de atención; la 2da llamada resultará en un golpe de castigo para el jugador(s) culpable en el grupo."}, {"icon": "AlertTriangle", "title": "Formato y corte", "body": "Stroke Play Individual a 54 hoyos. Categorías CAMP, AA y A: 100% handicap. Categorías B, C, D, E y Damas: 80% handicap. Corte a 36 hoyos: pasa el 40% de cada categoría (sin empates)."}]', 1)
ON DUPLICATE KEY UPDATE
  section_type = VALUES(section_type),
  content = VALUES(content),
  enabled = 1,
  updated_at = CURRENT_TIMESTAMP;

INSERT INTO convocatoria_content (torneoid, section_id, section_type, content, enabled) VALUES (365, 'reglas_locales', 'accordion', '[{"titulo": "Responsabilidad del jugador", "contenido": "ES RESPONSABILIDAD DEL JUGADOR CONOCER LAS REGLAS DE GOLF, LAS CONDICIONES DE LA COMPETENCIA Y LAS REGLAS LOCALES.\\nRegirán las Reglas de Golf de la USGA, así como las siguientes Condiciones de Competencia y Reglas Locales, mismas que dejan sin efecto otras utilizadas en otros torneos, incluyendo las propias del score card del Club o cualquier otro documento.\\nSe designa al Sr. Alfonso Navarro como Árbitro del Torneo. Asistencia de Reglas: Tel. 662 104 7508.\\nLa penalidad por infringir alguna de las presentes será de dos golpes."}, {"titulo": "Formato", "contenido": "Stroke Play Individual (juego por golpes) a 54 hoyos."}, {"titulo": "Categorías y hándicap", "contenido": "Categorías CAMP, AA y A: 100% handicap. Corte después de 36 hoyos.\\nCategorías B, C, D, E y Damas: 80% handicap. Corte después de 36 hoyos."}, {"titulo": "Corte a 36 hoyos", "contenido": "Todas las categorías: pasa el 40% de cada categoría (SIN EMPATES)."}, {"titulo": "Seniors en categorías A, B y C", "contenido": "Jugadores de 70 años en adelante podrán jugar de las salidas blancas aplicando la conversión correspondiente a su HDCP. Es obligación del jugador avisar que jugará de marcas blancas."}, {"titulo": "Desempate para los tres primeros lugares", "contenido": "Play off por tarjeta, usando total del hoyo 10 al 18, después del hoyo 13 al 18, y por último del hoyo 16 al 18; si persiste el empate, se aplica el mismo procedimiento en los hoyos 1 al 9. Este procedimiento se aplicará en todas las categorías excepto para el primer lugar en Campeonato, mismo que se determinará por Muerte Súbita, comenzando de un hoyo determinado por el Comité. En caso de tres o más empates se jugará únicamente por el 1er lugar; el 2do. y 3er. lugar se define por tarjeta."}, {"titulo": "Desempates para el corte a 36 hoyos", "contenido": "Todas las categorías: playoff por tarjeta, usando total del hoyo 10 al 18, después el hoyo 18 hacia atrás; si persiste el empate, se aplica el mismo procedimiento en los hoyos 1 al 9."}, {"titulo": "Límites de score neto a 36 hoyos", "contenido": "CAT. AA y A: 136. CAT. B, C, D, E y Damas: 140. Si durante el torneo algún jugador termina por debajo de 136 o 140 neto, será ajustado para la ronda del domingo. (Ejemplo: con límite a 140 score neto, si un 18 de HDCP en la Categoría C tira 138 neto, oficialmente será 140, pero jugará el domingo con 16 de handicap y quedará en la misma categoría.) No hay límite de score para el domingo."}, {"titulo": "Descalificación", "contenido": "Cuando un jugador es descalificado pierde posición y derecho a reclamar algún premio.\\n• Las fotos de las promociones del torneo son solo para fines de exhibición.\\n• Para los regalos que se entregan en la rifa del cóctel de bienvenida, el jugador o ganador tendrá que estar presente, excepto en la rifa del efectivo.\\n• El Comité del Torneo se reserva el derecho de hacer los cambios necesarios a este evento para asegurar que sea un Torneo de Golf exitoso."}, {"titulo": "Mal tiempo", "contenido": "En caso de inclemencia del tiempo, el Comité de Reglas avisará a los jugadores cómo proceder y determinará el número de hoyos para completar el Torneo de Golf."}, {"titulo": "Regla 1 — Jugar el campo como se encuentra", "contenido": "El jugador juega el campo como lo encuentra y la bola como reposa, salvo que bajo la protección específica de alguna regla se obtenga alivio con o sin penalidad."}, {"titulo": "Áreas de penalización", "contenido": "Todas las áreas de penalización son rojas y están marcadas con líneas y/o estacas rojas. Proceder bajo la Regla 17.1d."}, {"titulo": "Zonas de dropeo (Regla 14.3)", "contenido": "Cuando la bola del jugador de las categorías A, B, C, D, E y Damas se encuentre en áreas de penalización, tienen la opción de jugar en las zonas de dropeo marcadas con círculo blanco o bien tomar alivio con una de las opciones según la 17.1d (dos bastones por donde cruzó el área de penalización por última vez). En ambos casos sumando un golpe de penalización.\\nUbicación de zonas de dropeo: hoyos 8, 10, 12 y 13 — después del área de penalización (enfrente del lago). Hoyo 12 — 40 yardas antes del green."}, {"titulo": "Obstrucciones inamovibles (Regla 16)", "contenido": "Alivio sin castigo si interfieren en su stance, bola o swing: punto más cercano más un palo de golf.\\na) Retenidas de cable o madera que dan apoyo a los árboles. El árbol no es obstrucción.\\nb) Muros de madera que retienen el agua de los lagos de los hoyos 4, 5, 12, 17 y 18. Si su bola se encuentra en el bunker debe ser dropeada en el bunker y si está en el área general ahí debe dropearse.\\nc) Casa de bombeo localizada entre los hoyos 13 y 17: utilizar la zona de dropeo marcada con un círculo específico para cada hoyo."}, {"titulo": "Terreno en reparación", "contenido": "Marcado con línea blanca. Alivio sin penalización cuando su bola toca o está en o sobre la condición anormal del campo, o ésta interfiere físicamente en el stance o swing pretendido. El punto más cercano de alivio más un palo, sin acercarse al hoyo. Regla 16.1b."}, {"titulo": "Bola enterrada por su propio impacto (Regla 16.3)", "contenido": "Alivio sin penalización sólo cuando la bola está enterrada en una parte del área general cortada a nivel de fairway o menor. El alivio bajo esta regla no está permitido si la bola está enterrada en arena o en una parte del área general que no está cortada a la altura del fairway o menor."}, {"titulo": "Zonas de juego prohibido (Regla 16.1f)", "contenido": "Alivio sin castigo si interfieren en su stance, bola o swing. Punto más cercano de alivio más un palo de golf.\\na) Árboles (baby trees): aplica sólo para los árboles marcados con pintura azul.\\nb) Piedras de ornato de color rojizo o gris que se encuentran antes del lago del hoyo 14 (lado derecho) y en el lado izquierdo del green del hoyo 2 (hoyo 2 utilizar zona de dropeo).\\nc) Plantas de ornato antes de la salida del hoyo 3: utilizar zona de dropeo."}, {"titulo": "Pinos que indican yardas", "contenido": "Árboles 100, 150, 200, 250 yardas: NO HAY ALIVIO."}, {"titulo": "Agujeros de aireación", "contenido": "No se consideran terreno en reparación y por lo tanto la bola debe jugarse como se encuentre."}, {"titulo": "Banderas", "contenido": "Roja: frente. Blanca: medio. Azul: atrás."}, {"titulo": "Cambio de bola (Regla 14.3)", "contenido": "No se permite el cambio de bola en el green. Incurrirá en penalidad si lo hace."}, {"titulo": "Jugando dos bolas cuando hay dudas (Regla 20.1c)", "contenido": "Un jugador que tiene dudas sobre cómo proceder durante el juego de un hoyo puede completarlo con dos bolas, sin penalización, e informar al comité."}, {"titulo": "Otras recomendaciones", "contenido": "Recuerde que las Reglas contemplan:\\n• Marcar su bola para identificación.\\n• No acomodar la bola en ningún momento.\\n• No hay dadas, hay que embocar.\\n• No se puede cambiar la bola sobre el green ni en ninguna otra parte, a menos que una Regla lo permita.\\n• No se pueden usar más de 14 bastones.\\n• Sólo podrá contratar a un caddie a la vez.\\n• No se puede dar ni recibir consejo."}, {"titulo": "Cierre de la competencia", "contenido": "La competencia se considera cerrada en el momento del inicio de la ceremonia de premiación."}]', 1)
ON DUPLICATE KEY UPDATE
  section_type = VALUES(section_type),
  content = VALUES(content),
  enabled = 1,
  updated_at = CURRENT_TIMESTAMP;

